import{_ as a,o as t,c as i,ao as s}from"./chunks/framework.CVnxSqzg.js";const u=JSON.parse(`{"title":"What's new in 0.7.1","description":"","frontmatter":{},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md","lastUpdated":null}`),o={name:"whats-new.md"};function n(r,e,l,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="What&#39;s-new-in-0.7.1" tabindex="-1">What&#39;s new in 0.7.1 <a class="header-anchor" href="#What&#39;s-new-in-0.7.1" aria-label="Permalink to &quot;What&#39;s new in 0.7.1 {#What&#39;s-new-in-0.7.1}&quot;">​</a></h1><p>0.7.1 was released on 2026-11-18; 0.7.0 came before it. This page lists what 0.7.1 adds to 0.7.0, and one feature that 0.7.0 already had, marked so. On a Mac, press Cmd where this page says Ctrl.</p><h2 id="Slack" tabindex="-1">Slack <a class="header-anchor" href="#Slack" aria-label="Permalink to &quot;Slack {#Slack}&quot;">​</a></h2><ul><li><p>A project&#39;s Slack channel in a <a href="/ship-of-tools/stable/guide/chat#What-the-panel-shows">Chat drawer</a> (<code>Ctrl+k</code>): messages, threads, posts.</p></li><li><p>The chat is <a href="/ship-of-tools/stable/guide/chat-setup#Connect-your-first-Slack-workspace">set up from the window</a> (<code>Ctrl+Shift+k</code>); each project can use a channel of a <a href="/ship-of-tools/stable/guide/chat-setup#Connect-another-Slack-workspace">different workspace</a>.</p></li><li><p>A post from the drawer <a href="/ship-of-tools/stable/guide/chat#What-happens-when-you-post">appears in the channel as the person&#39;s own message</a>, from their Slack account.</p></li><li><p><a href="/ship-of-tools/stable/guide/chat#Pictures">Pictures in the channel</a> show in the drawer; a click on one, or <code>Ctrl+o</code> in the drawer, opens it in the preview.</p></li><li><p>From the drawer, <code>Ctrl+u</code> <a href="/ship-of-tools/stable/guide/chat#Posting-a-file">posts the previewed file to the channel</a>.</p></li><li><p>A session&#39;s agent, when asked, can <a href="/ship-of-tools/stable/guide/chat#The-agent-in-the-channel">post text and files to its project&#39;s channel</a>.</p></li></ul><h2 id="Drawing" tabindex="-1">Drawing <a class="header-anchor" href="#Drawing" aria-label="Permalink to &quot;Drawing {#Drawing}&quot;">​</a></h2><ul><li><p>An image in the preview <a href="/ship-of-tools/stable/guide/drawing#Drawing-on-an-image">can be drawn on</a> (<code>d</code>); a Claude Code session&#39;s agent is given the image with the drawing on it at the next prompt.</p></li><li><p>A <a href="/ship-of-tools/stable/guide/drawing#The-canvas">blank canvas</a> to draw on (<code>Shift+d</code>), given to the agent the same way.</p></li></ul><h2 id="Session-ordering" tabindex="-1">Session ordering <a class="header-anchor" href="#Session-ordering" aria-label="Permalink to &quot;Session ordering {#Session-ordering}&quot;">​</a></h2><ul><li>Already in 0.7.0: the session strip, the row of session names above the window&#39;s bottom border, has three <a href="/ship-of-tools/stable/ref/keybindings#Default-actions">orders</a>, by state, alphabetical and by recent activity; <code>Ctrl+Shift+o</code> moves to the next.</li></ul><h2 id="Other" tabindex="-1">Other <a class="header-anchor" href="#Other" aria-label="Permalink to &quot;Other {#Other}&quot;">​</a></h2><ul><li><p><a href="/ship-of-tools/stable/ref/config#display">Smoother scrolling</a> in the preview, the agent pane and the Terminal and REPL drawers; the Chat drawer scrolls the same way.</p></li><li><p><a href="/ship-of-tools/stable/guide/drawing#Selecting-text">Text selected in the preview</a> is given to a Claude Code session&#39;s agent at its next prompt.</p></li><li><p><a href="/ship-of-tools/stable/guide/previews#Built-in-file-types">SVG files</a> preview as pictures.</p></li><li><p>PDF pages and a video&#39;s poster frame preview on a computer with no poppler or ffmpeg installed: <a href="/ship-of-tools/stable/guide/previews#Built-in-file-types">Julia&#39;s copy is downloaded once</a>, at the first such preview.</p></li></ul><h2 id="Fixed" tabindex="-1">Fixed <a class="header-anchor" href="#Fixed" aria-label="Permalink to &quot;Fixed {#Fixed}&quot;">​</a></h2><p>Faults fixed since 0.7.0:</p><ul><li><p>A new Claude Code session stopped at a question about trusting a folder when Claude Code was at version 2.1.326.</p></li><li><p>The agent pane could not scroll <a href="/ship-of-tools/stable/guide/interface#The-Agent-Pane">a Claude Code session&#39;s conversation</a> when Claude Code used its fullscreen display.</p></li><li><p>Keys typed in the agent pane while the window was connecting to a session were lost.</p></li><li><p>A long line copied from the agent pane pasted as several lines, broken where the pane had wrapped it.</p></li><li><p>When the computer that runs the sessions started up, all its sessions started at once; they now <a href="/ship-of-tools/stable/guide/interface#The-lines-around-the-tree">start a few seconds apart</a>.</p></li><li><p>A zoomed PDF page could show the words &quot;binary file&quot; in place of the page.</p></li></ul><h2 id="Updating" tabindex="-1">Updating <a class="header-anchor" href="#Updating" aria-label="Permalink to &quot;Updating {#Updating}&quot;">​</a></h2><ul><li><p>Each computer on 0.7.0 <a href="/ship-of-tools/stable/guide/updating#What-updates-a-machine">downloads 0.7.1 by itself</a>, and the window shows a notice.</p></li><li><p>A computer changes to the downloaded version the next time the Ship of Tools window is launched on it, or its service is restarted.</p></li><li><p><a href="/ship-of-tools/stable/guide/updating#updating">Running the installer</a> updates a computer without waiting for that.</p></li><li><p>Sessions keep running through the update; each session&#39;s Julia REPL starts again, without its variables.</p></li><li><p>A session started on 0.7.0 is given a drawing or a selection only after it is <a href="/ship-of-tools/stable/guide/drawing#When-the-window-says-held">ended and started again</a>.</p></li><li><p>The chat, a drawing and a selection need 0.7.1 on the computer that runs the sessions and on the computer with the window.</p></li><li><p>The window&#39;s bottom border reads <code>fe &lt;version&gt; · be &lt;version&gt;</code>: the window&#39;s version, then that of the service that runs the shown session.</p></li></ul>',15)])])}const w=a(o,[["render",n]]);export{u as __pageData,w as default};
